const CAROUSEL_TOTAL = 24;
let carouselIndex = 0;
function carouselRender(){
  const img = document.getElementById('carouselImg');
  const counter = document.getElementById('carouselCounter');
  if (!img) return;
  const n = String(carouselIndex + 1).padStart(2, '0');
  img.src = `images/carousel/photo-${n}.jpg`;
  img.alt = `AI微型論壇台南場現場花絮 ${carouselIndex + 1}`;
  counter.textContent = `${carouselIndex + 1} / ${CAROUSEL_TOTAL}`;
}
let carouselTimer = null;
function carouselResetTimer(){
  if (carouselTimer) clearInterval(carouselTimer);
  carouselTimer = setInterval(carouselNext, 4000);
}
function carouselPrev(){
  carouselIndex = (carouselIndex - 1 + CAROUSEL_TOTAL) % CAROUSEL_TOTAL;
  carouselRender();
  carouselResetTimer();
}
function carouselNext(){
  carouselIndex = (carouselIndex + 1) % CAROUSEL_TOTAL;
  carouselRender();
}
function initPhotoCarousel(){
  carouselRender();
  carouselResetTimer();
}

document.addEventListener('DOMContentLoaded', () => {
  initNavbar();
  initBackToTop();
  initPhotoCarousel();
});

document.addEventListener('keydown', (e) => {
  if(e.key === 'Escape'){
    const sm = document.getElementById('successModal');
    const rm = document.getElementById('registerModal');
    const tm = document.getElementById('typeModal');
    if(sm.classList.contains('show')) hideSuccessModal();
    else if(rm.classList.contains('show')) hideRegisterModal();
    else if(tm.classList.contains('show')) hideTypeModal();
  }
});

// URL hash 直達報名：?register / #register / #報名 都觸發
window.addEventListener('load', () => {
  const h = location.hash.toLowerCase();
  const s = location.search.toLowerCase();
  if(h === '#register' || h === '#報名' || s.includes('register')){
    showTypeModal();
  }
});
</script>
</body>

